#include <iostream>
#include <print>

int main() {
    int age = 0;
    bool has_ticket = false;

    std::print("输入年龄 和 是否有票(1/0): ");
    std::cin >> age >> has_ticket;

    std::println("年龄够 且 有票 = {}", age >= 18 && has_ticket);
    std::println("年龄够 或 有票 = {}", age >= 18 || has_ticket);
    std::println("是小孩 或 没票 = {}", age < 18 || !has_ticket);
    std::println("都不成立吗 = {}", !(age >= 18 && has_ticket));

    return 0;
}

